package com.aiplacementos.app.database.entity

import androidx.room.Entity

/**
 * One question slot within a challenge, cached locally as each is revealed by the backend
 * (the backend only ever hands back the single current question, same withholding rule as
 * regular assessments -- future questions aren't known until reached) so the screen can
 * render the current question and running progress instantly on reopen, without a network
 * round trip. (clientAlarmId, questionIndex) is a natural composite key, not an
 * autogenerated one -- an upsert must replace the same slot in place, never accumulate
 * duplicate rows for it. optionsJson is the 4 MCQ options serialized as a JSON string array
 * -- Room has no native List<String> column type without a TypeConverter, and a single small
 * JSON blob here avoids introducing one for just this.
 */
@Entity(tableName = "challenge_questions", primaryKeys = ["clientAlarmId", "questionIndex"])
data class ChallengeQuestionEntity(
    val clientAlarmId: String,
    val questionIndex: Int,
    val backendQuestionId: Int,
    val skillTag: String,
    val prompt: String,
    val optionsJson: String,
    val isCorrect: Boolean = false,
)
